const submitFrameworkScope = `-- name: SubmitFrameworkScope :one
UPDATE framework_scopes
SET state = 'review',
    updated_at = now()
WHERE tenant_id = $1 AND id = $2 AND state = 'draft'
RETURNING id, tenant_id, framework_version_id, name, created_at, updated_at, state, predicate, predicate_hash, approver_user_id, approved_at, predicate_hash_at_approval, approval_evidence_file_url, approval_evidence_file_hash, effective_from, superseded_by, superseded_at
`

type SubmitFrameworkScopeParams struct {
	TenantID pgtype.UUID `json:"tenant_id"`
	ID       pgtype.UUID `json:"id"`
}

// AC-6: draft -> review. Guarded so callers can never re-submit an already
// under-review row by accident (would still be valid but masks bugs).
func (q *Queries) SubmitFrameworkScope(ctx context.Context, arg SubmitFrameworkScopeParams) (FrameworkScope, error) {
	row := q.db.QueryRow(ctx, submitFrameworkScope, arg.TenantID, arg.ID)
	var i FrameworkScope
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.FrameworkVersionID,
		&i.Name,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.State,
		&i.Predicate,
		&i.PredicateHash,
		&i.ApproverUserID,
		&i.ApprovedAt,
		&i.PredicateHashAtApproval,
		&i.ApprovalEvidenceFileUrl,
		&i.ApprovalEvidenceFileHash,
		&i.EffectiveFrom,
		&i.SupersededBy,
		&i.SupersededAt,
	)
	return i, err
}

const supersedePreviousActivated = `-- name: SupersedePreviousActivated :exec
UPDATE framework_scopes
SET state = 'superseded',
    superseded_by = $3,
    superseded_at = now(),
    updated_at = now()
WHERE tenant_id = $1
  AND framework_version_id = $2
  AND id <> $3
  AND state = 'activated'
`

type SupersedePreviousActivatedParams struct {
	TenantID           pgtype.UUID `json:"tenant_id"`
	FrameworkVersionID pgtype.UUID `json:"framework_version_id"`
	SupersededBy       pgtype.UUID `json:"superseded_by"`
}

// AC-8: in the same transaction as ActivateFrameworkScope, transition the
// previously-activated row (if any) to `superseded`, point its
// superseded_by at the new row, stamp superseded_at = now(). Skips the
// new row itself (id <> @new_id) so a re-running activation is idempotent.
func (q *Queries) SupersedePreviousActivated(ctx context.Context, arg SupersedePreviousActivatedParams) error {
	_, err := q.db.Exec(ctx, supersedePreviousActivated, arg.TenantID, arg.FrameworkVersionID, arg.SupersededBy)
	return err
}

const updateFrameworkScopePredicate = `-- name: UpdateFrameworkScopePredicate :one
UPDATE framework_scopes
SET predicate = $3,
    predicate_hash = $4,
    updated_at = now()
WHERE tenant_id = $1 AND id = $2
RETURNING id, tenant_id, framework_version_id, name, created_at, updated_at, state, predicate, predicate_hash, approver_user_id, approved_at, predicate_hash_at_approval, approval_evidence_file_url, approval_evidence_file_hash, effective_from, superseded_by, superseded_at
`

type UpdateFrameworkScopePredicateParams struct {
	TenantID      pgtype.UUID `json:"tenant_id"`
	ID            pgtype.UUID `json:"id"`
	Predicate     []byte      `json:"predicate"`
	PredicateHash string      `json:"predicate_hash"`
}

// Patch the predicate. The BEFORE UPDATE trigger
// (framework_scopes_bounce_on_predicate_change_trg) ensures that if this row
// was in `review` or `approved`, NEW.state falls back to `draft` and the
// approval columns are nulled. Application code reads back the row state to
// surface the `approval_invalidated` banner per AC-9.
func (q *Queries) UpdateFrameworkScopePredicate(ctx context.Context, arg UpdateFrameworkScopePredicateParams) (FrameworkScope, error) {
	row := q.db.QueryRow(ctx, updateFrameworkScopePredicate,
		arg.TenantID,
		arg.ID,
		arg.Predicate,
		arg.PredicateHash,
	)
	var i FrameworkScope
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.FrameworkVersionID,
		&i.Name,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.State,
		&i.Predicate,
		&i.PredicateHash,
		&i.ApproverUserID,
		&i.ApprovedAt,
		&i.PredicateHashAtApproval,
		&i.ApprovalEvidenceFileUrl,
		&i.ApprovalEvidenceFileHash,
		&i.EffectiveFrom,
		&i.SupersededBy,
		&i.SupersededAt,
	)
	return i, err
}

